#!/usr/bin/env bash
# Installs OpenCode 2 (npm package @opencode/cli) in the image. Runs as root
# at build time.
#   $1  version: an npm version or tag, or "default" (latest)
set -euo pipefail

version="${1:-default}"
[[ "$version" == default ]] && version=latest

# The npm postinstall picks the native binary for the platform.
npm install -g "@opencode/cli@${version}"
opencode --version
npm cache clean --force

# System configuration directory, regenerated by setup.sh on every start.
install -d -o dev -g "$(id -g dev)" /etc/opencode
